/* Little-irrep sections built from other tables:
 * - little_irr_full_matrices_position: the stored positions of every irrep of a space group, the identity and then each
 *   element (in element order) not generated by those before it;
 * - little_irr_full_matrices_irr_pointer: where each irrep's positions start, the irreps with matrices being those of
 *   a space group;
 * - little_irr_full_matrices_pointer: where each stored matrix starts in the sparse triples (each matrix lists its
 *   entries by column, then row, so a new one starts where that order drops);
 * - little_irr_full_dim: the number of entries of the stored identity matrix (0 for an irrep without matrices);
 * - little_irr_old: the old (data_irreps) id, which the irreps at k points without parameters take in gid order;
 * - little_irr_irrnum: the local number, the smallest one at the same (sg, k) not taken, in gid order, by an irrep or by
 *   its partner (little_irr_cc);
 * - little_irr_type: 3 with a partner, 2 with a real form (little_irr_real2_pointer), otherwise 1 (0 for an empty slot). */

#include <stdlib.h>
#include <string.h>

#include "geometry.h"
#include "tables.h"

int section_find_stored(const char *name, section_view *view);

enum { NAMES = 7 };
static const char *const names[NAMES] = {"little.little_irr_full_dim", "little.little_irr_old", "little.little_irr_full_matrices_pointer",
                                         "little.little_irr_full_matrices_position", "little.little_irr_full_matrices_irr_pointer",
                                         "little.little_irr_irrnum", "little.little_irr_type"};

static struct {
    int ready, failed;
    int64_t *data[NAMES];
    blob_section entries[NAMES];
} D;

/* the greedy generating positions of a space group's elements; returns their number */
static int seed_positions(int sg, int *out)
{
    int64_t records[GEO_MAX_OPS][5];
    int n = geo_sg_records(sg, records), m = 1;
    unsigned char in[73] = {0};
    if (n <= 0) return 0;
    out[0] = 1;
    in[records[0][4]] = 1;
    for (int i = 1; i < n; i++) {
        if (in[records[i][4]]) continue;
        out[m++] = i + 1;
        int list[GEO_MAX_OPS], size = 0;
        memset(in, 0, sizeof in);
        list[size++] = (int)records[0][4];
        in[records[0][4]] = 1;
        for (int a = 0; a < size; a++)
            for (int c = 0; c < m; c++) {
                int x = (int)geo_point_product(list[a], (int)records[out[c] - 1][4]);
                if (x >= 1 && x <= 72 && !in[x] && size < GEO_MAX_OPS) in[x] = 1, list[size++] = x;
            }
    }
    return m;
}

static int build(void)
{
    section_view sg, kslot, k_dim, lattice, triples, partner, real2;
    if (geo_load() || section_find_stored("little.little_irr_space_group", &sg) || section_find_stored("little.little_irr_k", &kslot) ||
        section_find_stored("little.little_irr_cc", &partner) || section_find_stored("little.little_irr_real2_pointer", &real2) ||
        section_find_stored("little.little_k_dim", &k_dim) || section_find_stored("space.ispace_lattice", &lattice) ||
        section_find_stored("little.little_irr_full_matrices", &triples))
        return 1;
    int64_t count = section_count(&sg), entries = section_count(&triples) / 3, last = 0, positions = 0, olds = 0;
    int seeds[231][GEO_MAX_OPS], nseeds[231] = {0};
    for (int s = 1; s <= 230; s++)
        if (!(nseeds[s] = seed_positions(s, seeds[s]))) return 1;
    for (int64_t g = 0; g < count; g++) {
        int64_t s = section_int(&sg, g);
        if (s >= 1 && s <= 230) last = g + 1, positions += nseeds[s];
    }
    int64_t counts[NAMES] = {count, count, positions + 1, positions, last + 1, count, count};
    for (int i = 0; i < NAMES; i++) {
        if (!(D.data[i] = calloc((size_t)counts[i] + 1, sizeof(int64_t)))) return 1;
        strncpy(D.entries[i].name, names[i], BLOB_NAME_SIZE - 1);
        D.entries[i].kind = BLOB_I64;
        D.entries[i].count = (uint64_t)counts[i];
        D.entries[i].bytes = (uint64_t)counts[i] * sizeof(int64_t);
    }
    int64_t *dims = D.data[0], *old = D.data[1], *pointer = D.data[2], *position = D.data[3], *irr = D.data[4], *number = D.data[5], *type = D.data[6];
    static uint64_t taken[231][28];
    memset(taken, 0, sizeof taken);
    for (int64_t g = 0; g < count; g++) {
        int64_t s = section_int(&sg, g), k = section_int(&kslot, g), cc = section_int(&partner, g), n = 1;
        if (s < 1 || s > 230 || k < 1 || k > 27) continue;
        while (n < 64 && (taken[s][k] >> n & 1)) n++;
        if (n >= 64 || cc < 0 || cc >= 64) return 1;
        number[g] = n;
        type[g] = cc ? 3 : g < section_count(&real2) && section_int(&real2, g) ? 2 : 1;
        taken[s][k] |= (uint64_t)1 << n | (uint64_t)1 << cc;
    }
    for (int64_t g = 0; g <= last; g++) irr[g] = 1;
    for (int64_t g = 0, used = 0; g < last; g++) {
        int64_t s = section_int(&sg, g);
        if (s < 1 || s > 230) continue;
        irr[g] = used + 1;
        for (int i = 0; i < nseeds[s]; i++) position[used++] = seeds[s][i];
        irr[g + 1] = used + 1;
    }
    int64_t matrices = 0;
    for (int64_t t = 0; t < entries; t++) {
        int64_t row = section_int(&triples, 3 * t), col = section_int(&triples, 3 * t + 1);
        int64_t prow = t ? section_int(&triples, 3 * t - 3) : 0, pcol = t ? section_int(&triples, 3 * t - 2) : 0;
        if (!t || col < pcol || (col == pcol && row <= prow)) {
            if (matrices == positions) return 1;
            pointer[matrices++] = t + 1;
        }
    }
    if (matrices != positions) return 1;
    pointer[matrices] = entries + 1;
    for (int64_t g = 0; g < count; g++) {
        int64_t s = section_int(&sg, g), k = section_int(&kslot, g);
        if (s < 1 || s > 230 || k < 1 || k > 27) continue;
        dims[g] = pointer[irr[g]] - pointer[irr[g] - 1];
        if (section_int(&k_dim, (section_int(&lattice, s - 1) - 1) * 27 + k - 1) == 0) old[g] = ++olds;
    }
    return 0;
}

/* section_find for the sections above; *handled 0 for any other name */
int little_derived_section(const char *name, section_view *view, int *handled)
{
    int which = -1;
    for (int i = 0; i < NAMES && which < 0; i++)
        if (!strncmp(name, names[i], BLOB_NAME_SIZE)) which = i;
    *handled = which >= 0;
    if (!*handled) return 1;
    if (!D.ready && !D.failed) {
        D.failed = build();
        D.ready = !D.failed;
    }
    if (!D.ready) return 1;
    view->entry = &D.entries[which];
    view->data = (const unsigned char *)D.data[which];
    return 0;
}

/* the dimension of little irrep gid, 0 when unknown */
int little_full_dim(int gid)
{
    section_view view;
    if (section_find("little.little_irr_full_dim", &view) || gid < 1 || gid > section_count(&view)) return 0;
    return (int)section_int(&view, gid - 1);
}

/* the old (data_irreps) id of little irrep gid, 0 when it has none */
int little_old_id(int gid)
{
    section_view view;
    if (section_find("little.little_irr_old", &view) || gid < 1 || gid > section_count(&view)) return 0;
    return (int)section_int(&view, gid - 1);
}
